    , FILE_ORG_NM
    , FILE_SAVE_NM
    , FILE_PATH
    , FILE_SIZE
    , FILE_CONTENT_TYPE
	, REG_ID
	, REG_DT  
	, UPD_ID
	, UPD_DT
    )
  VALUES (
     #{fileRefNo}
   , #{fileRefType}
   , #{fileOrgNm}
   , #{fileSaveNm}
   , #{filePath}
   , #{fileSize}
   , #{fileContentType}
   , #{regId}
